// Shared fixtures: inputs, a fake GitHub, faux models, and scratch git repositories.
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

import type { Api, Context, Model, Tool } from "@earendil-works/pi-ai";
import { createModels } from "@earendil-works/pi-ai/models";
import { fauxProvider } from "@earendil-works/pi-ai/providers/faux";
import { onTestFinished, vi } from "vitest";

import { DEFAULTS } from "./defaults.ts";
import type { GitHubClient } from "./github.ts";
import type { ActionInputs } from "./inputs.ts";
import type { Logger } from "./run.ts";
import { DEFAULT_SNAPSHOT_LIMITS } from "./storage/worktree.ts";
import type { GitHubComment, TriggerInfo } from "./types.ts";

/** A Logger whose methods are typed mocks. */
export function createLogger(): Logger {
	return {
		info: vi.fn<Logger["info"]>(),
		debug: vi.fn<Logger["debug"]>(),
		warning: vi.fn<Logger["warning"]>(),
		error: vi.fn<Logger["error"]>(),
		setFailed: vi.fn<Logger["setFailed"]>(),
		setOutput: vi.fn<Logger["setOutput"]>(),
		startGroup: vi.fn<Logger["startGroup"]>(),
		endGroup: vi.fn<Logger["endGroup"]>(),
	};
}

const since = (list: GitHubComment[], iso?: string) =>
	iso
		? list.filter((c) => Date.parse(c.created_at) >= Date.parse(iso))
		: [...list];

/**
 * A mock GitHub client. `comments` and `reviewComments` back the list methods (live arrays: tests may push to
 * them), and posted comment bodies are recorded in `posted`.
----

	it("reports the tools the model gets", async () => {
		const { models, model } = fauxModels();
		const thread = await Thread.open({
			cwd: tempDir(),
			models,
			model,
			log: createLogger(),
			extensions: [pit],
			tools: { exclude: [], hidden: ["read", "write", "edit", "bash"] },
		});
		await thread.close();
		expect(thread.modelTools).toStrictEqual(["typescript"]);
	});

	it("fails when the model would get no tools", async () => {
		const { models, model } = fauxModels();
		await expect(
			Thread.open({
				cwd: tempDir(),
				models,
				model,
				log: createLogger(),
				tools: { exclude: ["bash"], hidden: ["*"] },
			}),
		).rejects.toThrow(
			"exclude_tools and model_tools_hidden leave the model with no tools (it would have read, write, edit, bash)",
		);
	});
});

